    "notebook": "chap3.ipynb",
    "cell": 8,
    "code": "%matplotlib ipympl\nimport scipy.io\nfrom scipy.io.wavfile import read, write\n\nwav_file = read(read_path + 'audio/C5.wav')\nfs = wav_file[0]\nsig = wav_file[1][:, 0]\ndt = 1 / fs\nN = sig.size\nt = np.arange(sig.size) * dt\nf0 = 523.25 # Middle C (C5)\n\nplt.close()\nplt.figure(figsize=(10, 4))\nax1 = plt.subplot(1, 2, 1)\nax2 = plt.subplot(1, 2, 2)\n\nfreq, psd = scipy.signal.welch(sig, fs = fs, nperseg = N // 8)\n\nax1.plot(freq, psd, 'k.-')\nax1.set_yscale('log')\n\n# Peak Detection for C4.wav\npeak_idx, _ = scipy.signal.find_peaks(np.log10(psd), prominence = 0.5, distance = 50, height = -1)\npeak_idx = peak_idx[1:-2]\n\n# Peak Detection for C5.wav\npeak_idx, _ = scipy.signal.find_peaks(np.log10(psd), prominence = 0.5, distance = 100, height = -2)\npeak_idx = peak_idx[1:]\n\nax1.plot(freq[peak_idx], psd[peak_idx], 'ro')\n\nax1.set_xlim(0, 7000)\nax1.set_xlabel('Frequency [Hz]')\nax1.set_ylabel('Power Spectral Density\\n[Arb$^2$/Hz]')\n\nax2.plot(np.arange(1, peak_idx.size + 1), freq[peak_idx], 'ro')\n\nax2.set_xlabel('Harmonic Number')\nax2.set_ylabel('Frequency [Hz]')\n\nimport scipy.optimize\npopt, pcov = scipy.optimize.curve_fit(lambda n, B: f0 * n * np.sqrt(1 + B * n * n), np.arange(1, peak_idx.size + 1), freq[peak_idx], p0 = [1e-4])\nB = popt[0]\n\nn = np.arange(0.5, peak_idx.size + 1.5)\nax2.plot(n, f0 * n, 'k-', alpha = 0.3, label = '$nf_0$')\nax2.plot(n, f0 * n * np.sqrt(1 + B * n * n), 'C1-', alpha = 0.3, label = '$nf_0\\sqrt{1+Bn^2}$\\n' + f'$B$={B:.1e}')\nax2.xaxis.set_major_locator(ticker.MultipleLocator(1))\nax2.legend(loc='upper left', frameon=False, ncol = 1, labelcolor=\"linecolor\", handlelength = 0, handletextpad = 0, )\n\nax2.autoscale(enable=True, axis='x', tight=True)\n\nplt.tight_layout()\nplt.savefig(save_path + 'figure_piano_harmonic' + '.png',bbox_inches='tight',dpi=300)\n\nplt.show()"
