  "figure_lombscargle_data_missing.png": {
    "notebook": "chap3.ipynb",
    "cell": 20,
    "code": "import numpy as np\nimport matplotlib.pyplot as plt\nimport scipy.signal\nimport scienceplots\nplt.style.use(['science', 'nature', 'notebook', 'grid', 'high-vis'])\n\n%matplotlib ipympl\nplt.close()\n\nplt.figure(figsize=figsize_normal)\nax1 = plt.subplot(2, 1, 1)\nax2 = plt.subplot(2, 1, 2)\n\nomega0 = 2 * np.pi * 5.25\n\nt = np.linspace(0, 1, 500, endpoint=False)\nfs = 1 / (t[1] - t[0])\nsig = np.sin(omega0 * t) + np.sin(omega0 * 3.2 * t) + np.random.randn(t.size) * 0.01\n\nax1.plot(t, sig, '-', alpha = 1.)\n\ncoefs = np.fft.rfft(sig)\nfreq = np.fft.rfftfreq(len(t), t[1] - t[0])\n\n\n# Data Missing\ndata_miss_idx = np.random.choice(np.arange(t.size), t.size - 200)\nsig[data_miss_idx] = np.nan\n\n# Randomly Sampling\n# t = np.random.uniform(0, 1, 300)\n# t.sort()\n# sig = np.sin(omega0 * t) + np.sin(omega0 * 3.2 * t) + np.random.randn(t.size) * 0.01\nls_amp = np.abs(scipy.signal.lombscargle(t[~np.isnan(sig)], sig[~np.isnan(sig)], 2 * np.pi * freq[1:], normalize='amplitude'))\n\n\nax1.plot(t, sig, 'C1x')\n\nls_amp = np.abs(scipy.signal.lombscargle(t[~np.isnan(sig)], sig[~np.isnan(sig)], 2 * np.pi * freq[1:], normalize='amplitude'))\n\nax2.stem(freq[1:], -ls_amp * freq.size, linefmt = 'C1--', markerfmt = 'C1o', basefmt = 'C1-', label = 'Lomb-Scargle')\n\nax2.stem(freq, np.abs(coefs), linefmt = 'C0-', markerfmt = 'C0o', basefmt = 'C0-', label = 'Ground Truth')\n\n\nax1.set_title('Data Missing', **title_font)\n# ax1.set_title('Randomly Sampling', **title_font)\nax1.set_xlabel('Time [s]')\nax1.set_ylabel('Magnitude\\n[Arb]')\n\n\nax2.set_title('Fourier Transform', **title_font)\nax2.set_xlabel('Frequency [Hz]')\nax2.set_ylabel('Coefficient\\n[Arb]')\n\nax2.set_xlim(0, 20)\nax2.set_ylim(-330, 330)\n\nax1.autoscale(enable=True, axis='x', tight=True)\nax2.legend(loc = 'upper center', ncol = 1, labelcolor=['C1', 'C0'], frameon = False)\n\nplt.tight_layout()\n\n\nplt.savefig(save_path + 'figure_lombscargle_data_missing' + '.png',bbox_inches='tight',dpi=300)\n# plt.savefig(save_path + 'figure_lombscargle_randomly_sampling' + '.png',bbox_inches='tight',dpi=300)\n\nplt.show()"
  },
