    "code": "import numpy as np\nimport matplotlib.pyplot as plt\nimport scipy.signal\nimport scienceplots\nplt.style.use(['science', 'nature', 'notebook', 'grid', 'high-vis'])\n\n%matplotlib ipympl\nplt.close()\n\nplt.figure(figsize=figsize_normal)\nax1 = plt.subplot(2, 1, 1)\nax2 = plt.subplot(2, 1, 2)\n\nradial_velocity_df = pd.read_csv(read_path + 'UID_0113357_RVC_001.tbl.txt', skiprows = 21, sep = '\\s+', header = None).iloc[:179, :]\nt = radial_velocity_df[0].values\nsig = radial_velocity_df[1].values\nsig_err = radial_velocity_df[2].values\n\n# ax1.plot(t, sig, 'C0.', alpha = 1.)\nax1.errorbar(t, sig, yerr = sig_err, fmt = 'C0.', alpha = 1., label = 'Original', capsize = 3)\n\nperiod = np.linspace(0, 10, 1000)[1:]\nfreq = 1 / period\nomega = 2 * np.pi * freq\nls_coef = scipy.signal.lombscargle(t[~np.isnan(sig)], sig[~np.isnan(sig)], omega, normalize='amplitude', weights = 1 / sig_err[~np.isnan(sig)]**2)\n# ls_coef = scipy.signal.lombscargle(t[~np.isnan(sig)], sig[~np.isnan(sig)], omega, normalize='amplitude')\nls_power = np.abs(ls_coef * ls_coef)\n\nidx_peak = np.argmax(ls_power)\nomega_peak = omega[idx_peak]\nfreq_peak = freq[idx_peak]\namp_peak = ls_coef[idx_peak]\nphase_peak = np.angle(ls_coef[idx_peak], deg = True)\nprint(amp_peak, 1 / freq_peak)\nt_uniform = np.linspace(t.min(), t.max(), 10000)\nax1.plot(t_uniform, (amp_peak.conj() * np.exp(1j * omega_peak * t_uniform)).real, 'C1-', label = f'Lomb-Scargle\\nT={period[idx_peak]:.2f} day\\nPhase={phase_peak:.1f} deg')\n# ax2.stem(period, np.abs(ls_coef), linefmt = 'C0-', markerfmt = 'C0o', basefmt = 'C0-', label = 'Lomb-Scargle')\nax2.fill_between(period, 0 * np.abs(ls_coef), np.abs(ls_coef), alpha = 0.5, color = 'C0')\n\n\n# ax1.set_title('Data Missing', **title_font)\n# ax1.set_title('Randomly Sampling', **title_font)\nax1.set_xlabel('Julian Date [day]')\nax1.set_ylabel('Radial Velocity\\n[m/s]')\n\nax1.set_title('51 Pegasi @ Lick Observatory', **title_font)\n\nax2.set_title('Lomb-Scargle Periodgram', **title_font)\nax2.set_xlabel('Period [day]')\nax2.set_ylabel('Coefficient\\n[Arb]')\n\n# ax2.set_xlim(0, 20)\n# ax2.set_ylim(-330, 330)\n# ax1.set_xlim(2450000, 2450000 + 60)\nax2.axvline(4.23, color = 'C1', linestyle = '--', label = '51 Pegasi b\\nT = 4.23 day')\n\nperiod_longest = (t.max() - t.min()) / 2\nperiod_shortest = np.diff(t).mean() * 2\n# ax2.axvline(period_longest, color = 'k', linestyle = '--')\nax2.axvline(period_shortest, color = 'k', linestyle = '--', label = f'Nyquist Limit\\nT = {np.diff(t).mean() * 2:.2f} day')\n\n\nax1.autoscale(enable=True, axis='x', tight=True)\nax2.autoscale(enable=True, axis='x', tight=True)\nax2.set_ylim(0, 60)\nax2.legend(loc = 'upper right', ncol = 1, frameon = False)\n\nplt.tight_layout()\n\n\nplt.savefig(save_path + 'figure_lombscargle_51Pegasib' + '.png',bbox_inches='tight',dpi=300)\n\nplt.show()"
