  "figure_seismic_waves.png": {
    "notebook": "practical_spectral_analysis_plot.ipynb",
    "cell": 17,
    "code": "from obspy import UTCDateTime\nfrom obspy.clients.fdsn import Client\n\n# 连接IRIS服务\nclient = Client(\"IRIS\")\n\nstarttime = UTCDateTime(\"2008-05-12T06:30:01\")\nendtime = UTCDateTime(\"2008-05-12T06:45:00\")\n# 下载波形数据（垂向BHZ）\nst = client.get_waveforms(\n    network=\"IC\", station=\"WMQ\", location=\"00\", channel=\"BHZ\",\n    starttime=starttime,\n    endtime=endtime\n)\n\n\n# 下载台站元数据（响应信息）\ninv = client.get_stations(\n    network=\"IC\", station=\"WMQ\", level=\"response\",\n    starttime=starttime,\n    endtime=endtime\n)\nst.remove_response(inventory=inv, output=\"VEL\")  \n\n\n%matplotlib ipympl\nplt.close()\nplt.cla()\nplt.clf()\nplt.figure(figsize=(8, 6))\nax1 = plt.subplot(1, 1, 1)\ndt = 1 / st.traces[0].stats.sampling_rate\nt = np.datetime64(starttime) + (np.arange(0, len(st[0].data)).astype(float) * dt * 1e3).astype('timedelta64[ms]')\nsig = np.array(st[0].data, dtype=float) * 1e3\nax1.plot(t, sig, 'k-')\n\n# ax1.fill_between(t, -np.abs(scipy.signal.hilbert(sig) * 1e3), np.abs(scipy.signal.hilbert(sig) * 1e3), color='C0', alpha=0.2, label='Envelope')\n\n# -------- 1. 小波分解 --------\nimport pywt\nwavelet = 'db4'\nlevel   = 20\ncoeffs  = pywt.wavedec(sig, wavelet, mode='periodization', level=level)\ncA_L, *cDs = coeffs        # cDs = [D_L, D_{L-1}, …, D_1]\n\n# -------- 2. 逐层重构到原长度 N --------\nN      = len(sig)\nreconA = pywt.upcoef('a', cA_L, wavelet, level=level, take=N)\nreconDs = np.array([pywt.upcoef('d', cD, wavelet, level=lev, take=N)\n           for lev, cD in zip(range(level, 0, -1), cDs)])\n\nreconDs_std = np.std(reconDs, axis=1)\n\noffset = 0.0\nidx = 0\nfor i in range(len(reconDs)):\n    if reconDs_std[i] > 0.05:\n        offset -= 5\n        ax1.plot(t, offset + reconDs[i], color = f\"C{idx}\", linestyle = '-', label =f'D{i + 1} [{reconDs_std[i]:.2f}]', zorder = 10 - i)\n        ax1.text(\n            t[-1] - np.timedelta64(30, 's'),\n            offset + 1 + reconDs[i][-1],\n            f'Level {level - i}\\n' + r'[$\\mathbf{\\sigma^2}=$' + f'{reconDs_std[i]:.2f}]',\n            fontsize=12,\n            color=f\"C{idx}\",\n            ha='right',\n            va='bottom',\n            weight='bold'\n        )\n        idx += 1\n\n# ax1.legend(ncol = 2)\n# ax1.set_ylim(-6.99, 7)\nax1.set_ylim(-28, 8)\nax1.set_xlabel('UTC [HH:MM]')\nax1.set_ylabel('Velocity [mm/s]')\nax1.set_title('Broadband High-Gain Vertical Seismometer\\n' + f\"[{st[0].id}]\", **title_font)\nax1.autoscale(axis = 'x', tight = True)\nax1.xaxis.set_major_locator(mdates.MinuteLocator(interval=2))\nax1.xaxis.set_major_formatter(mdates.ConciseDateFormatter(ax1.xaxis.get_major_locator()))\nax1.xaxis.set_minor_locator(ticker.AutoMinorLocator())\nax1.text(np.datetime64('2008-05-12T06:33:00'), 2.1, 'P Waves', fontsize=14, color='w', ha='center', va='center', weight = 'bold', path_effects = path_effect)\nax1.text(np.datetime64('2008-05-12T06:36:00'), 2.1, 'S Waves', fontsize=14, color='w', ha='center', va='center', weight = 'bold', path_effects=path_effect)\nax1.text(np.datetime64('2008-05-12T06:40:00'), 6.8, 'Surface Waves', fontsize=14, color='w', ha='center', va='center', weight = 'bold', path_effects=path_effect)\nax1.text(t[-1] + np.timedelta64(60, 's'), -13.5, 'Discrete Wavelet [Daubechies-4]\\nDecomposition', fontsize=14, color='k', rotation = 90, ha='center', va='center', weight = 'bold')\n\n# ax1.yaxis.set_label_coords(-0.08, 0.5)\nplt.tight_layout()\nplt.savefig(save_path + 'figure_seismic_waves' + '.png',bbox_inches='tight',dpi=300)\nplt.show()"
  },
