    "code": "plt.close()\nax1 = plt.subplot(1, 1, 1)\n\n\nN = 128\nt = np.linspace(0, 1, N, endpoint=False)\ndt = t[1] - t[0]\nfs = 1 / dt\n\nomega0 = 2 * np.pi * fs / 2.02\n\nsig = np.sin(omega0 * t) + np.random.randn(t.size) * 0.0\n# ax1.plot(time, signal, 'k-', label = 'Signal')\nax1.plot(t, sig, 'rs-', label=r'$\\mathit{f_s}=$' + ' %d Hz' % fs, zorder = 1)\n\nN = 2 ** 10\nt = np.linspace(0, 1, N, endpoint=False)\ndt = t[1] - t[0]\nfs = 1 / dt\n\nsig = np.sin(omega0 * t) + np.random.randn(t.size) * 0.0\nax1.plot(t, sig, 'k-', label=r'$\\mathit{f_s}=$' + ' %d Hz' % fs, zorder = 0)\n\n\n# plt.title('Signal')\nplt.xlabel('Time [s]')\nplt.ylabel('Intensity [Arb]')\n\nax1.set_xlim(0, 1)\nax1.set_ylim(-1.2, 1.2)\n\nax1.legend(loc='upper right', frameon=False, ncol = 1, bbox_to_anchor=(1.03, 1.4))\nax1.set_title('Aliasing\\n' + r'$\\mathit{f_0}=%.1f Hz$' % (omega0 / 2 / np.pi),  **title_font)\n\nplt.tight_layout()\n\nplt.savefig(save_path + 'figure_aliasing_nyquist' + '.png',bbox_inches='tight',dpi=300)\n\nplt.show()"
