    "code": "import matplotlib.patheffects as pe\n# import matplotlib\nplt.close()\nplt.figure(figsize = (16, 9))\nax1 = plt.subplot()\nN = 2 ** 10\nt = np.linspace(0, 1, N, endpoint = False)\nax1.plot(t, scipy.signal.gausspulse(t - 0.5, 10) + t ** 1 + 2, 'C0-', linewidth = 15, path_effects = [pe.withStroke(linewidth=20,\n                                                        foreground=\"w\", alpha = 0.6)])\nax1.plot(t, scipy.signal.gausspulse(t - 0.5, 6) + t ** 1, 'C1-', linewidth = 15, path_effects = [pe.withStroke(linewidth=20,\n                                                        foreground=\"w\", alpha = 0.6)])\nax1.plot(t, scipy.signal.gausspulse(t - 0.5, 2) + t ** 1 - 2, 'C2-', linewidth = 15, path_effects = [pe.withStroke(linewidth=20,\n                                                        foreground=\"w\", alpha = 0.6)])\nax1.set_facecolor('#666666')\n# ax1.axis('off')\nplt.setp(ax1.xaxis.get_majorticklabels(), visible = False)\nplt.setp(ax1.yaxis.get_majorticklabels(), visible = False)\nax1.grid(which = 'both', axis = 'both', visible = False)\nax1.set_xticks([])\nax1.set_yticks([])\nax1.spines['bottom'].set_visible(False)\nax1.spines['top'].set_visible(False)\nax1.spines['left'].set_visible(False)\nax1.spines['right'].set_visible(False)\nplt.tight_layout()\nplt.savefig(save_path + 'figure_icon' + '.png',bbox_inches='tight',dpi=300)\n\nplt.show()"
