    "code": "import pywt\nimport ssqueezepy\nfrom scipy.io.wavfile import read\n\nwav_file = read('Data/whistling.wav')\nfs = wav_file[0]\nsig = wav_file[1][:, 0]\ndt = 1 / fs\nN = len(sig)\nt = np.arange(N) * dt\n\nplt.close()\nplt.figure(figsize=(8, 4))\nplt.subplots_adjust(hspace = 0.02, right = 0.80, bottom = 0.15, left = 0.15)\n\nax1 = plt.subplot(2, 1, 1)\nax2 = plt.subplot(2, 1, 2, sharex=ax1)\nfrom mpl_toolkits.axes_grid1.inset_locator import inset_axes\nax1ins = inset_axes(ax1, width=\"18%\", height=\"30%\", loc=\"upper right\")\nax1ins.set_ylim(-1.4e4, 1.4e4)\n# ax1ins.set_facecolor('#DDDDDD')\n\nindicator = ax1.indicate_inset_zoom(ax1ins, edgecolor=\"C1\", alpha = 0.5, linestyle = '--', facecolor = 'C1')\nindicator[1][0].set_visible(False)\nindicator[1][1].set_visible(True)\nindicator[1][2].set_visible(True)\nindicator[1][3].set_visible(False)\nax1ins.set_xticks([])\nax1ins.set_yticks([])\n\nax1.plot(t, sig, 'k-', linewidth = 1.0)\nax1ins.plot(t, sig, 'k-', linewidth = 1.0)\nax1ins.set_xlim(0.470, 0.475)\nscales = 2 ** np.linspace(1, 6, 50, endpoint = False)\n\nbandwidth = 24.0\ncoef, scales = ssqueezepy.cwt(sig, ('morlet', {'mu': bandwidth}), scales = bandwidth / (2 * np.pi) * scales.astype(np.float32), fs = 1 / dt, l1_norm = False)\nfreq = bandwidth / (2 * np.pi) / dt / scales\ndf = (freq[0] / freq[1] - 1) * freq / np.sqrt(freq[0] / freq[1])\npsd = (np.abs(coef) ** 2) * (2 * dt)\npc2 = ax2.pcolormesh(t, freq, np.log10(psd), cmap=cmap, vmax=6.0, vmin=-1.0, zorder = 0, rasterized = True)\n\nax1.set_title('Whistling', **title_font)\n\n# ax1.yaxis.set_major_formatter(ticker.FormatStrFormatter('%.0e'))\n\n\nax2.set_yscale('log')\n\nax2.set_xlabel('Time [s]')\nax1.set_ylabel('Intensity\\n' + '[Arb]')\nax2.set_ylabel('Frequency\\n[Hz]')\n\nax1.ticklabel_format(axis = 'y', style = 'sci', scilimits=(0, 0), useMathText=True)\nplt.setp(ax1.get_xticklabels(), visible=False)\n\n# plt.tight_layout()\n\nfig = plt.gcf()\ncbar_ax2 = fig.add_axes(\n    [ax2.get_position().x1 + 0.01, ax2.get_position().y0, 0.02, ax2.get_position().y1 - ax2.get_position().y0])\ncbar2 = plt.colorbar(pc2, cax=cbar_ax2)\ncbar2.ax.xaxis.set_label_position('top')\ncbar2.ax.xaxis.set_ticks_position('top')\ncbar2.ax.tick_params(which='major', length=4, direction='in', pad=3)\n# cbar2.ax.xaxis.set_ticks([])\ncbar2.ax.set_ylabel(r'$\\mathrm{log_{10}(PSD)}$' + '\\n$\\mathrm{[Arb^2 \\cdot Hz^{-1}]}$')\n\nax1.yaxis.set_label_coords(-0.09, 0.5)\nax2.yaxis.set_label_coords(-0.09, 0.5)\n\nax2.tick_params(color = 'w', which = 'both')\nax2.grid(color = 'w')\n# plt.tight_layout()\nplt.savefig(save_path + 'figure_whistling' + '.png',bbox_inches='tight',dpi=300)\n\nplt.show()"
